import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default async function createNode(config, ctx) {
  const { THREE } = ctx;

  // Extract text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const textContent = textItem?.text ?? 'Collection 1';

  // Create container group
  const group = new THREE.Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    gsap.killTweensOf(group);
    group.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  // Load texture asset
  let texture = null;
  if (config.imageUrl) {
    texture = await ctx.textureLoader.loadTexture(config.imageUrl);
    texture.colorSpace = 'srgb';
  }

  // === BACKDROP PLANE ===
  // Create engineered gradient surface as stage backdrop
  const backdropGeom = new THREE.PlaneGeometry(7, 6);

  // Build gradient material using TSL nodes
  const gradientNode = mix(
    vec3(0.0667, 0.0667, 0.0627),  // surface #0b0b10 (near-black)
    vec3(0.0859, 0.0859, 0.0941),  // slight lift toward #161719
    uv().y  // vertical gradient
  );

  const backdropMaterial = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    side: THREE.DoubleSide,
    toneMapped: false
  });

  const backdropMesh = new THREE.Mesh(backdropGeom, backdropMaterial);
  backdropMesh.position.z = -2.5;
  backdropMesh.receiveShadow = false;
  group.add(backdropMesh);

  // === TEXT LABEL ===
  // Render headline text via ctx.fontAtlas
  const textObj = ctx.fontAtlas.createText(textContent, {
    fontSize: 39,
    color: '#e8ecf2',  // paper color
    align: 'center'
  });
  textObj.position.y = 0.3;
  textObj.position.z = 0.1;
  group.add(textObj);

  // === TEXTURED SPRITE PLANE ===
  // Atlas region: 512x320 pixels; assume 1:1 aspect in scene units
  // Aspect ratio: 512/320 = 1.6
  const spriteAspect = 512 / 320;
  const spriteHeight = 1.2;  // Scene-unit height
  const spriteWidth = spriteHeight * spriteAspect;

  const spriteGeom = new THREE.PlaneGeometry(spriteWidth, spriteHeight);

  // Create material with texture map
  let spriteMaterial;
  if (texture) {
    spriteMaterial = new MeshBasicNodeMaterial({
      mapNode: uv().convert('vec4').mul(vec3(1, 1, 1)).add(vec3(texture)),
      map: texture,
      side: THREE.DoubleSide,
      toneMapped: false,
      transparent: true,
      alphaTest: 0.01
    });
  } else {
    // Fallback: solid accent color if texture missing
    spriteMaterial = new MeshBasicNodeMaterial({
      colorNode: vec3(1.0, 0.165, 0.22),  // #ff2a38 (accent)
      side: THREE.DoubleSide,
      toneMapped: false
    });
  }

  const spriteMesh = new THREE.Mesh(spriteGeom, spriteMaterial);
  spriteMesh.position.y = -0.6;
  spriteMesh.position.z = 0.05;
  group.add(spriteMesh);

  // === SUBTLE GRAIN OVERLAY ===
  // Create a noise/grain effect via a second plane with procedural texture
  const grainGeom = new THREE.PlaneGeometry(spriteWidth, spriteHeight);
  const grainMaterial = new MeshBasicNodeMaterial({
    colorNode: vec3(0.1, 0.1, 0.1),
    side: THREE.DoubleSide,
    toneMapped: false,
    transparent: true,
    opacity: 0.04
  });
  const grainMesh = new THREE.Mesh(grainGeom, grainMaterial);
  grainMesh.position.copy(spriteMesh.position);
  grainMesh.position.z += 0.001;  // Slight z-offset to layer over sprite
  group.add(grainMesh);

  // === IDLE FLOAT ANIMATION ===
  // Subtle breathing motion on the sprite card
  gsap.fromTo(
    spriteMesh.position,
    { y: spriteMesh.position.y },
    {
      y: spriteMesh.position.y + 0.08,
      duration: 2.5,
      ease: 'sine.inOut',
      repeat: -1,
      yoyo: true
    }
  );

  return group;
}
